"use strict";
const byId=id=>document.getElementById(id);
const courseById=id=>COURSES.find(c=>c.id===id);
const targetById=id=>CAMPUSES.find(t=>t.id===id);
const dialog=byId("detail-dialog");
let toastTimer,explorerQuery="",explorerCategory="All";
const link=(url,label)=>'<a href="'+url+'" target="_blank" rel="noopener noreferrer">'+escapeHTML(label)+' ↗</a>';
function notify(message){byId("toast").textContent=message;byId("toast").classList.add("visible");clearTimeout(toastTimer);toastTimer=setTimeout(()=>byId("toast").classList.remove("visible"),3000)}
function relationship(c,t){const agreement=isCS()?ASSIST_AGREEMENTS[t.id]:null;if(agreement){const match=agreement.matches[c.id];if(match)return{kind:"verified",label:match.receiving,note:c.code+" articulates to "+match.receiving+" ("+match.title+") for "+agreement.program+" in the "+agreement.year+" ASSIST agreement.",program:agreement.program,year:agreement.year,published:agreement.published,source:agreement.source,programNote:match.programNote||""};if(agreement.reviewed.includes(c.id))return{kind:"unknown",label:"Not listed in reviewed agreement",note:c.code+" was not found as an articulated sending course in the reviewed "+agreement.program+" "+agreement.year+" agreement.",program:agreement.program,year:agreement.year,published:agreement.published,source:agreement.source,reviewed:true};}if(t.id==="ucsd"&&c.verified)return{kind:"verified",label:c.verified,note:"Published UCSD department equivalency; individual year/grade applicability still needs review.",source:SOURCES.ucsdMath};if(isCS()&&["ucsd","sdsu","csusm"].includes(t.id)&&c.targets.includes(t.id))return{kind:"demo",label:"Illustrative CS match",note:"Sample mapping only—not an official articulation."};return{kind:"unknown",label:"Major match not verified",note:"Catalog lists general "+t.system+" transferability; this is not a confirmed "+escapeHTML(PLAN.major)+" requirement match."}}
function applicable(c){return chosenCampuses().filter(t=>relationship(c,t).kind!=="unknown")}
function getStats(){const r={completed:0,registered:0,planning:0,completedUnits:0,registeredUnits:0,planningUnits:0,contributions:0,helped:0};for(const c of selectedRecords()){const s=statusOf(c.id);r[s]++;r[s+"Units"]+=c.units;if(s==="planning")r.contributions+=applicable(c).length}r.helped=chosenCampuses().filter(t=>selectedRecords().some(c=>statusOf(c.id)==="planning"&&relationship(c,t).kind!=="unknown")).length;return r}
function readState(){return{view:PLAN.view,college:PLAN.college,major:PLAN.major,targetIds:[...PLAN.targetIds],statuses:{...PLAN.statuses},...getStats(),mode:"Demo; user-entered status, static ASSIST Computer Science agreement snapshot for Berkeley, UCLA and Cal Poly Pomona, two UCSD department relationships, limited illustrative matches elsewhere"}}
function showDialog(title,html){byId("dialog-title").textContent=title;byId("dialog-body").innerHTML=html;if(!dialog.open)dialog.showModal()}
function showSources(){showDialog("Sources, coverage & privacy",'<div class="evidence-banner"><span class="evidence-icon">✓</span><div><strong>Official facts and sample logic stay separate.</strong><p>Source snapshot · September 13, 2026</p></div></div><div class="source-block"><h3>ASSIST Computer Science snapshot</h3><p>The demo now includes a frozen, source-linked snapshot of San Diego Mesa College major agreements: UC Berkeley Computer Science B.A. and EECS B.S. (2025–26), UCLA Computer Science B.S. (2025–26), and Cal Poly Pomona Computer Science B.S. (2026–27). Each matching cell shows the receiving course and agreement year. “Not listed” means the Mesa course was not found in that reviewed agreement; it is not a statement about admission or every possible program.</p>'+Object.values(ASSIST_AGREEMENTS).map(a=>'<p>'+link(a.source,a.program+' · '+a.year)+'</p>').join("")+'<p>This is static POC data, not live scraping. Approved API access should replace this snapshot with a maintained ingestion process.</p>'+link(SOURCES.assistApiDocs,"ASSIST agreement API documentation")+'</div><div class="source-block"><h3>SDCCD course catalog sample</h3><p>Seven Mesa courses have catalog-backed titles, units and general UC/CSU transferability. Your selected home college may be elsewhere in SDCCD, but every imported course example is explicitly a Mesa course.</p>'+link(SOURCES.catalog,"Mesa 2026–27 catalog")+'<p>'+link("https://www.sdccd.edu/students/college-catalogs/","All SDCCD catalogs")+'</p></div><div class="source-block"><h3>Other demo evidence</h3><p>Mesa MATH 150 → UCSD MATH 20A and MATH 151 → UCSD MATH 20B come from UCSD’s department table. UCSD, SDSU and CSU San Marcos still contain explicitly marked illustrative CS logic where ASSIST data has not been imported.</p>'+link(SOURCES.ucsdMath,"UCSD department table")+'<p>'+link(SOURCES.sdsuPathway,"SDSU–SDCCD pathway")+'</p></div><div class="source-block"><h3>Your entries are not verified academic records</h3><p>Completed, registered and planning are self-reported statuses. No grades, transcripts, prerequisites, GE, GPA, unit eligibility, deadlines, live sections or admission conditions are validated.</p><p>Your choices stay only in this tab’s memory. Refreshing starts over. Copying or downloading a summary includes the information shown in it.</p></div><p class="directory-links">'+link(SOURCES.classSearch,"Official SDCCD class search")+link(SOURCES.assist,"Open ASSIST")+link(SOURCES.assistTerms,"ASSIST reuse terms")+'</p>')}
function showCourse(id){const c=courseById(id);const evidence=chosenCampuses().map(t=>({t,m:relationship(c,t)}));showDialog(c.code+" · Course evidence",'<span class="source-pill verified school-inline">'+schoolBadge("mesa")+'San Diego Mesa · 2026–27 catalog</span><h3 class="detail-title">'+c.title+'</h3><div class="detail-facts"><span><strong>'+c.units+'</strong> units</span><span>UC/CSU transferable in catalog</span><span>'+STATUS_LABELS[statusOf(id)]+' · self-reported</span></div><div class="source-block"><h3>Your selected campuses</h3><div class="evidence-rows">'+evidence.map(({t,m})=>'<div><strong class="school-inline">'+schoolBadge(t.id)+t.name+'</strong><span><span class="match-pill '+m.kind+'">'+m.label+'</span><small>'+(m.year?m.program+' · '+m.year:m.note)+'</small></span></div>').join("")+'</div></div><div class="source-block"><h3>Official course information</h3><p>'+link(c.source,"Mesa course page")+' · '+link(SOURCES.catalog,"Catalog, printed page "+c.page)+'</p>'+evidence.filter(x=>x.m.source).map(({t,m})=>'<p><strong>'+t.name+':</strong> '+m.note+(m.programNote?' '+m.programNote:'')+' '+link(m.source,"View source")+'</p>').join("")+(evidence.some(x=>x.m.source)?'':'<p>No campus-major equivalency is verified for this course in the demo.</p>')+'</div><p class="scope-note">General transferability does not prove major applicability. Check the applicable agreement year, prerequisites, grades, course availability and enrollment eligibility with official sources.</p>'+link(SOURCES.classSearch,"Check actual sections"))}
function showTarget(id){const t=targetById(id);const records=selectedRecords();showDialog(t.name+" · "+PLAN.major,'<div class="school-heading">'+schoolBadge(t.id)+'<strong>'+t.name+'</strong></div><span class="source-pill">'+t.system+' · Selected destination</span><p>The following uses your course statuses. It is an applicability preview, not a complete eligibility audit.</p><div class="target-detail-list">'+(records.length?records.map(c=>{const m=relationship(c,t);return'<div><div><strong>'+c.code+'</strong><small>'+STATUS_LABELS[statusOf(c.id)]+' · Mesa · '+c.units+' units</small></div><span class="match-pill '+m.kind+'">'+m.label+'</span></div>'}).join(""):'<p>No coursework added yet. Add courses to begin this comparison.</p>')+'</div><div class="source-block"><h3>What to verify next</h3><p>Check whether '+escapeHTML(PLAN.major)+' is offered at this campus and use the applicable campus-major/year agreement. Unknown matches do not mean the course will not transfer.</p>'+link(SOURCES.assist,"Open ASSIST")+'<p>'+link(t.system==="UC"?"https://www.universityofcalifornia.edu/about-uc/campuses-locations":"https://www.calstate.edu/attend/campuses","Find official campus information")+'</p></div><p class="scope-note">Source-linked = published course relationship. Illustrative = demo assumption. Not verified = major-specific evidence unavailable. Registered/planned work is not completed.</p>')}
function summary(){const s=getStats();return "TRANSFER COPILOT — DEMO PLAN\nHome college: "+collegeName()+"\nIntended major: "+PLAN.major+"\nTargets: "+chosenCampuses().map(t=>t.name).join(", ")+"\n\n"+selectedRecords().map(c=>c.code+" — "+c.title+" | San Diego Mesa | "+c.units+" units | "+STATUS_LABELS[statusOf(c.id)]).join("\n")+"\n\nCompleted: "+s.completedUnits+" units (self-reported)\nRegistered: "+s.registeredUnits+" units (not completed)\nPlanning: "+s.planningUnits+" units (not completed)\n\n"+chosenCampuses().map(t=>t.name+"\n"+selectedRecords().map(c=>c.code+": "+relationship(c,t).label).join("\n")).join("\n\n")+"\n\nLIMITATIONS: Course catalog sample is Mesa only. Most campus-major relationships are illustrative or not verified. Registered/planned courses are not completed. No eligibility or admission guarantee, complete major audit, GE, GPA, prerequisite or live-seat verification. The website does not retain this profile. Sharing this summary includes the course selections above.\n\nMesa catalog: "+SOURCES.catalog+"\nUCSD math source: "+SOURCES.ucsdMath+"\nOfficial class search: "+SOURCES.classSearch}
function showShare(parent=false){const s=getStats();showDialog(parent?"Family & counselor view":"Share your planning summary",'<div class="share-heading">'+schoolBadge(PLAN.college)+'<div><h3>Your transfer picture</h3><p>'+escapeHTML(collegeName())+' · '+escapeHTML(PLAN.major)+'</p></div></div><p>'+chosenCampuses().map(t=>t.name).join(" · ")+'</p><div class="summary-tiles"><div><strong>'+s.completedUnits+'</strong><span>completed units*</span></div><div><strong>'+s.registeredUnits+'</strong><span>registered units</span></div><div><strong>'+s.planningUnits+'</strong><span>planning units</span></div></div><div class="summary-courses">'+selectedRecords().map(c=>'<div><strong>'+c.code+'</strong><span>'+c.title+'</span><span>'+STATUS_LABELS[statusOf(c.id)]+'</span></div>').join("")+'</div><div class="summary-caution"><strong>Questions for a counselor</strong><p>Which courses apply to my intended major at each campus? What else is required? Are prerequisites cleared and which agreement year applies?</p></div><p class="scope-note">*Completed is self-reported, not a certified transfer-unit total. A copy or download includes your selections. The demo link alone does not share your answers; everyone starts fresh.</p><div class="dialog-actions"><button class="button navy" data-action="copy-summary">Copy summary</button><button class="button outline" data-action="download-summary">Download summary</button><button class="button subtle" data-action="copy-link">Copy demo link</button></div>')}
function showWhy(){const s=getStats();showDialog("Why this scenario?",'<span class="source-pill">Transparent demo logic · No live AI</span><h3 class="detail-title">'+s.planning+' planning courses · '+s.planningUnits+' units</h3><p>Scenario buttons only change Planning or Not added courses. Your completed and registered coursework is preserved.</p><p>The demo prioritizes source-linked or illustrative matches for the destinations you selected. A lighter scenario limits newly planned units. It does not certify prerequisites, choose an optimal real schedule, or predict admission.</p><div class="checklist">'+selectedRecords().filter(c=>statusOf(c.id)==="planning").map(c=>'<div><span class="check-status">↗</span><span><strong>'+c.code+'</strong><br><small>'+applicable(c).map(t=>t.name).join(" · ")+'</small></span><strong>'+c.units+' units</strong></div>').join("")+'</div><div class="source-block"><h3>Transfer Efficiency — demo measure</h3><p>'+s.contributions+' source-linked or illustrative course–target contributions across '+s.planningUnits+' planned units. Unknown matches are excluded, not treated as academic failures. No universal score or completion percentage is produced.</p></div><button class="button outline" data-open="sources">Inspect the evidence</button>')}
function initials(){return "YOU"}
function setCourseStatus(id,status){if(!courseById(id)||!Object.hasOwn(STATUS_LABELS,status))throw new Error("Invalid course status");PLAN.statuses[id]=status;PLAN.scenario="custom";render();return readState()}
function setScenario(name){if(!["balanced","lighter","original"].includes(name))throw new Error("Unknown scenario");if(PLAN.view!=="dashboard")throw new Error("Complete the setup first");if(name==="original"){PLAN.statuses={...PLAN.baseline};PLAN.scenario="original";render();return readState()}const candidates=COURSES.filter(c=>!["completed","registered"].includes(statusOf(c.id))&&applicable(c).length>0);if(!candidates.length){notify("No supported scenario matches for these choices. Add planning courses manually.");return readState()}const order=name==="lighter"?["math151","cisc246","math150","cisc190","cisc187","phys195","phys196"]:["math151","cisc187","cisc246","math150","cisc190","phys195","phys196"];let units=0;for(const c of COURSES)if(statusOf(c.id)==="planning")PLAN.statuses[c.id]="none";for(const id of order){const c=candidates.find(c=>c.id===id);if(c&&units+c.units<=(name==="lighter"?8:12)){PLAN.statuses[c.id]="planning";units+=c.units}}PLAN.scenario=name;render();return readState()}
function renderTargets(){const records=selectedRecords();byId("target-list").innerHTML=chosenCampuses().map(t=>{const types=records.map(c=>relationship(c,t).kind);const v=types.filter(x=>x==="verified").length,d=types.filter(x=>x==="demo").length,u=types.filter(x=>x==="unknown").length;return'<button class="target-row" data-target="'+t.id+'" aria-label="View '+t.name+' applicability">'+schoolBadge(t.id)+'<span class="target-name"><strong>'+t.name+'</strong><small>'+v+' source-linked · '+d+' illustrative · '+u+' not verified</small></span><span class="chevron">↗</span></button>'}).join("");document.querySelector(".pathways .tiny-tag").textContent=PLAN.targetIds.size+" targets";document.querySelector(".pathways .muted").innerHTML=escapeHTML(PLAN.major)+' · <button class="text-button" data-action="edit-targets">Edit destinations</button>';document.querySelector(".pathways .small-note").textContent="Counts describe evidence for your selected course records—not completed requirements or admission odds."}
function renderCourses(){const s=getStats();byId("course-content").innerHTML='<div class="course-table-wrap"><table class="course-table"><thead><tr><th>Course status</th><th>Mesa course</th><th>Units</th><th>Selected-campus evidence</th><th>Details</th></tr></thead><tbody>'+COURSES.map(c=>'<tr class="'+(statusOf(c.id)==="none"?"course-off":"")+'"><td><select class="dashboard-status" data-plan-status="'+c.id+'" aria-label="Plan status for '+c.code+'">'+statusOptions(c.id)+'</select></td><td><button class="course-title" data-course-detail="'+c.id+'"><strong>'+c.code+'</strong><span>'+c.title+'</span></button></td><td>'+c.units+'</td><td><span class="evidence-count">'+(applicable(c).length?applicable(c).length+" source-linked / illustrative":"Major matches not verified")+'</span></td><td><button class="evidence-link" data-course-detail="'+c.id+'">View ↗</button></td></tr>').join("")+'</tbody></table></div><div class="plan-total"><span><strong>'+s.planning+' planning courses · '+s.planningUnits+' units</strong><span class="total-caption">'+s.registered+' registered separately; none counted as completed</span></span><button class="text-button" data-action="why">Why this scenario? ↗</button></div><div class="scenario-insight"><span class="insight-symbol">↔</span><p><strong>Your choices drive this plan.</strong> Change a status to update every selected campus. Scenario buttons preserve completed and registered work. This is not an enrollable schedule.</p></div>';
byId("risk-content").innerHTML='<div class="risk-item"><span class="risk-icon">!</span><div><h3>'+(s.planningUnits>12?"Review your planned workload":"Verify major applicability")+'</h3><p>'+(s.planningUnits>12?"Your planning list exceeds the demo’s 12-unit scenario limit. It may span multiple terms; review timing and workload with a counselor.":"Most matches are illustrative or unknown. Check the correct major agreement, course-taking year and prerequisites before making enrollment decisions.")+'</p></div><button class="text-button" data-open="sources">Review</button></div><div class="risk-item"><span class="risk-icon blue">i</span><div><h3>Registered does not mean completed</h3><p>'+s.registered+' registered and '+s.planning+' planning courses remain unfinished. GE, GPA, unit eligibility, dates and live availability are not assessed.</p></div><button class="text-button" data-action="share">Prepare questions</button></div>'}
function renderMatrix(){const rows=selectedRecords();byId("applicability-matrix").innerHTML='<div class="section-heading"><div><div class="eyebrow">YOUR COURSES × YOUR DESTINATIONS</div><h2>See where each course fits.</h2></div><span class="source-pill">Course relationships—not admission readiness</span></div><div class="matrix-legend"><span class="match-pill verified">Source-linked</span><span class="match-pill demo">Illustrative</span><span class="match-pill unknown">Not listed / not verified</span></div>'+(rows.length?'<div class="matrix-scroll" tabindex="0" aria-label="Course applicability comparison; scroll horizontally for more campuses"><table class="applicability-table"><thead><tr><th>Course & status</th>'+chosenCampuses().map(t=>'<th><span class="school-inline">'+schoolBadge(t.id)+t.name+'</span></th>').join("")+'</tr></thead><tbody>'+rows.map(c=>'<tr><th><button class="course-title" data-course-detail="'+c.id+'"><strong>'+c.code+'</strong><span class="status-text '+statusOf(c.id)+'">'+STATUS_LABELS[statusOf(c.id)]+'</span></button></th>'+chosenCampuses().map(t=>{const m=relationship(c,t);const detail=m.year?(m.kind==="verified"?"ASSIST · ":"Reviewed · ")+m.program+" · "+m.year:m.kind==="verified"?"Course equivalency; major need unconfirmed":m.kind==="demo"?"Not an official articulation":t.system+" transferability listed; major unknown";return'<td><span class="match-pill '+m.kind+'">'+m.label+'</span><small>'+detail+'</small>'+(m.source?'<button class="evidence-link" data-course-detail="'+c.id+'">Evidence ↗</button>':'')+'</td>'}).join("")+'</tr>').join("")+'</tbody></table></div>':'<div class="empty-state"><h3>Your course history starts here.</h3><p>Add a course status below to see its applicability to your selected campuses.</p></div>')+'<p class="field-help">ASSIST cells use a static Mesa agreement snapshot and show the agreement year. “Not listed” means the course was not found in that reviewed major agreement—not that it cannot transfer. General UC/CSU transferability does not establish major applicability.</p>'}
function renderExplorer(){const q=explorerQuery.toLowerCase();const list=COURSES.filter(c=>(explorerCategory==="All"||c.category===explorerCategory)&&(c.code+" "+c.title).toLowerCase().includes(q));byId("explorer-results").innerHTML=list.length?list.map(c=>'<article class="explorer-card"><div class="explorer-top"><span class="source-pill">'+c.category+'</span><span class="explorer-units">'+c.units+' units</span></div><button class="course-title" data-course-detail="'+c.id+'"><strong>'+c.code+'</strong><span>'+c.title+'</span></button><div class="college-label school-inline">'+schoolBadge("mesa")+'San Diego Mesa · 2026–27 catalog</div><div class="availability"><span>Live sections & seats</span><strong>Not checked</strong></div><div class="explorer-actions"><button class="button outline" data-explore-add="'+c.id+'">'+(statusOf(c.id)==="none"?"Add to planning":STATUS_LABELS[statusOf(c.id)]+" · View")+'</button>'+link(c.source,"Course page")+'</div></article>').join(""):'<div class="empty-state"><h3>No courses match this sample.</h3><button class="button outline" data-action="clear-search">Clear filters</button></div>';byId("result-count").textContent=list.length+" of 7 sample courses"}
function render(){if(PLAN.view!=="dashboard")return;const s=getStats();document.querySelector(".student strong").textContent="Your plan";document.querySelector(".student small").textContent=collegeName();byId("home-school-mark").innerHTML=schoolBadge(PLAN.college);document.querySelector(".workspace-profile>p").textContent=PLAN.major;document.querySelector("#overview h1").textContent="Here’s your transfer picture.";document.querySelector(".subheading").innerHTML=schoolBadge(PLAN.college)+escapeHTML(collegeName())+" · "+escapeHTML(PLAN.major)+" · "+PLAN.targetIds.size+" destinations";document.querySelector(".term-tag").textContent="Self-reported coursework";document.querySelector(".demo-notice>span:last-child").innerHTML='<strong>Your inputs. Transparent limits.</strong> Course statuses are self-reported; most major matches are illustrative or unknown. <button class="text-button" data-open="sources">Inspect the evidence ↗</button>';byId("plan-units").textContent=s.planningUnits;byId("plan-benefit").textContent=s.helped;document.querySelector(".recommendation h2").innerHTML=s.planning?"See the next step.<br> Understand the tradeoff.":"Your next step<br> starts with a course.";document.querySelector(".recommendation p").textContent=s.planning?s.planning+" planning courses contribute "+s.contributions+" source-linked or illustrative matches across your chosen campuses. Unknown matches still need review.":"You’ve brought "+s.completed+" completed and "+s.registered+" registered courses into view. Add planning courses to explore possible next steps.";document.querySelector(".recommendation-note").textContent="No complete eligibility or admissions assessment.";document.querySelector(".family-strip>span").innerHTML="<strong>A clearer conversation, together.</strong> Review your choices with a parent or counselor.";byId("course-status-strip").innerHTML=["completed","registered","planning"].map(k=>'<div><span class="status-dot '+k+'"></span><strong>'+s[k]+'</strong><span>'+STATUS_LABELS[k].toLowerCase()+'</span><small>'+s[k+"Units"]+' units*</small></div>').join("")+'<p>*Self-reported sample course units—not certified transferable totals.</p>';renderTargets();renderCourses();renderMatrix();renderExplorer();document.querySelectorAll("[data-scenario]").forEach(b=>{b.classList.toggle("selected",b.dataset.scenario===PLAN.scenario);b.setAttribute("aria-pressed",String(b.dataset.scenario===PLAN.scenario))});byId("live-status").textContent=s.completed+" completed, "+s.registered+" registered, "+s.planning+" planning courses."; }
document.addEventListener("click",async event=>{const b=event.target.closest("button");if(!b)return;if(b.dataset.open==="sources")return showSources();if(b.dataset.target)return showTarget(b.dataset.target);if(b.dataset.courseDetail)return showCourse(b.dataset.courseDetail);if(b.dataset.scenario)return setScenario(b.dataset.scenario);if(b.dataset.exploreAdd){const id=b.dataset.exploreAdd;if(statusOf(id)==="none"){setCourseStatus(id,"planning");notify("Course added to planning")}else showCourse(id);return}const a=b.dataset.action;if(a==="why")return showWhy();if(a==="share"||a==="parent")return showShare(a==="parent");if(a==="edit-profile")return beginEdit(1);if(a==="edit-targets")return beginEdit(2);if(a==="edit-courses")return beginEdit(4);if(a==="clear-search"){explorerQuery="";explorerCategory="All";byId("course-search").value="";byId("category-filter").value="All";return renderExplorer()}if(a==="confirm-reset"){dialog.close();return startOver()}if(a==="copy-summary"||a==="copy-link"){const text=a==="copy-summary"?summary():location.origin+location.pathname;try{await navigator.clipboard.writeText(text);notify(a==="copy-summary"?"Your summary was copied":"Demo link copied—answers are not included")}catch{showDialog("Copy your summary",'<p>Select and copy the text below.</p><textarea id="copy-fallback" readonly aria-label="Summary text"></textarea>');byId("copy-fallback").value=text;byId("copy-fallback").select()}return}if(a==="download-summary"){const url=URL.createObjectURL(new Blob([summary()],{type:"text/plain;charset=utf-8"}));const a=document.createElement("a");a.href=url;a.download="transfer-copilot-plan.txt";a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify("Your planning summary was downloaded")}});
document.addEventListener("change",e=>{if(e.target.dataset.planStatus)setCourseStatus(e.target.dataset.planStatus,e.target.value)});
byId("course-search").addEventListener("input",e=>{explorerQuery=e.target.value;renderExplorer()});
byId("category-filter").addEventListener("change",e=>{explorerCategory=e.target.value;renderExplorer()});
byId("close-dialog").addEventListener("click",()=>dialog.close());
dialog.addEventListener("click",e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
byId("reset").textContent="Start over";
byId("reset").addEventListener("click",()=>showDialog("Start a new plan?",'<p>This clears the college, destinations and course statuses in this tab. Download your summary first if you want to keep it.</p><button class="button navy" data-action="confirm-reset">Clear this plan & start over</button>'));
byId("share").addEventListener("click",()=>showShare());
const context=document.modelContext;
document.querySelectorAll('.workspace-header nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelectorAll('.workspace-header nav a').forEach(link=>{link.classList.toggle('active',link===a);if(link===a)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current')})}));
if(context?.registerTool){const life=new AbortController();window.addEventListener("pagehide",()=>life.abort(),{once:true});const register=tool=>{try{Promise.resolve(context.registerTool(tool,{signal:life.signal})).catch(()=>{})}catch{}};
register({name:"read_sample_transfer_plan",title:"Read current demo plan",description:"Read current course statuses, campus choices and counts. No name is collected. No official eligibility conclusion.",inputSchema:{type:"object",properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>readState()});
register({name:"configure_sample_scenario",title:"Configure planning scenario",description:"After onboarding, change only planning courses while preserving completed and registered records. No enrollment or saving.",inputSchema:{type:"object",properties:{scenario:{type:"string",enum:["balanced","lighter","original"]}},required:["scenario"],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:input=>{if(!input||Object.keys(input).some(k=>k!=="scenario"))throw new Error("Invalid input");return setScenario(input.scenario)}});
register({name:"configure_course_status",title:"Set a course status",description:"Update one Mesa sample course to completed, registered, planning, or not added. Self-reported demo only.",inputSchema:{type:"object",properties:{courseId:{type:"string",enum:COURSES.map(c=>c.id)},status:{type:"string",enum:Object.keys(STATUS_LABELS)}},required:["courseId","status"],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:input=>{if(PLAN.view!=="dashboard")throw new Error("Complete setup first");if(!input||Object.keys(input).some(k=>!["courseId","status"].includes(k)))throw new Error("Invalid input");return setCourseStatus(input.courseId,input.status)}});
}
